package io.imiocode.team.tool;
import com.fasterxml.jackson.databind.node.ObjectNode;import io.imiocode.team.model.TeamPrincipal;import io.imiocode.team.task.TeamTaskService;import io.imiocode.tool.*;import java.util.function.Supplier;
public final class TaskGetTool extends AbstractTaskTool {public TaskGetTool(TeamTaskService t,Supplier<TeamPrincipal> p,ToolLimits l,SecretRedactor r){super(def(),t,p,l,r);}private static ToolDefinition def(){ObjectNode s=schema();s.withObject("properties").putObject("task_id").put("type","string");s.putArray("required").add("task_id");return new ToolDefinition("TaskGet","读取当前团队的单个任务。",s,ToolRisk.LOW);}@Override protected ToolResult executeValidated(ObjectNode a){rejectUnknownFields(a,"task_id");return json(tasks.get(principal(),requireText(a,"task_id")));}}
